package io.github.fludakit.conditional;

import java.lang.annotation.Documented;
import java.lang.annotation.ElementType;
import java.lang.annotation.Retention;
import java.lang.annotation.RetentionPolicy;
import java.lang.annotation.Target;

/**
 * Holds the repeated {@link Conditional} annotations of a single element.
 * <p>
 * The container is required by the repeatable annotation mechanism of Java: it is generated by the compiler
 * and filled with the annotations that were written. It is not meant to be used directly, declaring several
 * {@code @Conditional} annotations is enough.
 * </p>
 * <p>
 * The container stays invisible in the deployment. A bean that declares several conditions reports the same
 * stereotypes as one that declares a single condition.
 * </p>
 *
 * @see Conditional
 */
@Documented
@Retention(RetentionPolicy.RUNTIME)
@Target({ ElementType.TYPE, ElementType.METHOD, ElementType.FIELD, ElementType.ANNOTATION_TYPE })
@Conditional({})
public @interface Conditionals {

    /**
     * The repeated conditions.
     *
     * @return the required conditions
     */
    Conditional[] value();
}
